  gap: 5px;
  flex-wrap: wrap;
  max-height: 62px;
  overflow: auto;
  flex-shrink: 0;
  padding-bottom: 6px;
}
.artifact-item {
  font-size: 8px;
  background: #afc49a10;
  border: 1px solid #afc49a22;
  border-radius: 4px;
  padding: 5px 6px;
  color: #b4c5a6;
}
.event-log {
  overflow: auto;
  flex: 1;
  min-height: 45px;
  padding-right: 4px;
  scrollbar-width: thin;
  scrollbar-color: #5a6c6533 transparent;
}
.event-item {
  border-left: 1px solid #a6ba9433;
  margin: 7px 0;
  padding: 1px 0 1px 9px;
}
.event-item strong {
  font-size: 9px;
  color: #c3d0bd;
  font-weight: 400;
}
.event-item p {
  font-size: 8px;
  line-height: 1.7;
  color: #899ba1;
  margin: 4px 0;
}
.event-empty {
  font-size: 9px;
  line-height: 1.8;
  color: #74858c;
}
.resident-card {
  right: 24px;
  top: 155px;
  width: 246px;
  padding: 17px;
}
.agent-badges {
  display: flex;
  gap: 6px;
  margin: 12px 0 5px;
}
.agent-badges span {
  font-size: 9px;
  padding: 4px 8px;
  border: 1px solid #ffffff13;
  border-radius: 5px;
  color: #bfceaf;
  background: #afc49a10;
}
.agent-badges #agent-state {
  color: #8f9da7;
  background: #0c141c55;
}
.agent-badges #agent-state[data-status="working"],
.agent-badges #agent-state[data-status="reviewing"],
.agent-badges #agent-state[data-status="testing"] {
  color: #e3d0a8;
  border-color: #cfb48655;
}
.agent-badges #agent-state[data-status="blocked"],
.agent-badges #agent-state[data-status="error"] {
  color: #e5ad99;
  border-color: #b7876e55;
}
.agent-badges #agent-state[data-status="done"] {
  color: #b4d3a5;
}
.agent-instance {
  font: 8px monospace;
  color: #697d89;
  margin: 6px 0;
}
.resident-description {
  min-height: 0;
  margin: 10px 0 15px;
}
.resident-info {
  margin: 16px 0 8px;
}
.resident-info p {
  font-size: 9px;
  max-width: 130px;
  line-height: 1.7;
}
.agent-actions {
  display: flex;
  gap: 8px;
  margin: 0 0 12px;
}
.agent-actions button {
  font-size: 9px;
  padding: 7px;
  border: 1px solid #ffffff15;
  border-radius: 5px;
  color: #b1c0b3;
  flex: 1;
  white-space: nowrap;
}
.resident-label[data-status="working"],
.resident-label[data-status="reviewing"],
.resident-label[data-status="testing"] {
  border-color: #ddc58f99;
  color: #efd9a8;
}
.resident-label[data-status="blocked"] {
  border-color: #df9c8377;
  color: #e4ac98;
}
.resident-label.speaking {
  box-shadow: 0 0 14px #d6e3bb33;
  border-color: #d6e3bb;
  background: #384d3df2;
}
.speech-bar {
  position: fixed;
  bottom: 150px;
  left: 50%;
  transform: translateX(-50%);
  width: min(480px, calc(100vw - 40px));
  border-radius: 12px;
  padding: 14px 18px;
}
.speech-top {
  display: flex;
  gap: 8px;
  align-items: center;
}
.speech-top strong {
  font-size: 11px;
  font-weight: 400;
  color: #d9e5c5;
}
.speech-top > span:last-of-type {
  font-size: 8px;
  color: #95a4a6;
  margin-left: auto;
}
.speech-top button {
  font-size: 8px;
  color: #93a095;
  padding: 3px;
  border-radius: 3px;
}
.speech-bar p {
  font-size: 12px;
  line-height: 1.8;
  color: #d2d7ca;
  margin: 9px 0 1px;
}
.speech-pulse {
  display: flex;
  gap: 2px;
  align-items: center;
  height: 15px;
}
.speech-pulse i {
  background: #c3d7a6;
  width: 2px;
  height: 4px;
  animation: voice-pulse 0.65s alternate infinite;
}
.speech-pulse i:nth-child(2) {
  animation-delay: -0.4s;
}
.speech-pulse i:nth-child(3) {
  animation-delay: -0.2s;
}
.artifact-dialog {
  width: min(90vw, 700px);
  max-height: 80vh;
  overflow: auto;
}
.artifact-dialog pre {
  font-family: inherit;
  white-space: pre-wrap;

