  criteriaLine: CRITERIA_LINE_LIMIT,
  criteriaLines: MAX_CRITERIA_LINES,
});

export class Narrator {
  constructor({
    onChange = () => {},
    onNotice = () => {},
    audioId = "agent-voice-audio",
  } = {}) {
    this.onChange = onChange;
    this.onNotice = onNotice;
    this.audio = new Audio();
    this.audio.id = audioId;
    this.audio.hidden = true;
    document.body.append(this.audio);
    this.audio.preload = "auto";
    this.audio.volume = 0.9;
    this.enabled = true;
    this.paused = false;
    this.current = null;
    this.context = null;
    this.analyser = null;
    this.finish = null;
    this.fetchController = null;
    this.generation = 0;
  }
  async unlock() {
    if (!this.context) {
      this.context = new AudioContext();
      this.analyser = this.context.createAnalyser();
      this.analyser.fftSize = 256;
      const source = this.context.createMediaElementSource(this.audio);
      source.connect(this.analyser);
      this.analyser.connect(this.context.destination);
      this.samples = new Uint8Array(this.analyser.frequencyBinCount);
    }
    await this.context.resume();
  }
  getLevel() {
    if (!this.current || this.audio.paused || !this.analyser) return 0;
    this.analyser.getByteFrequencyData(this.samples);
    return Math.min(
      1,
      this.samples.reduce((sum, value) => sum + value, 0) /
        this.samples.length /
        75,
    );
  }
  setEnabled(value) {
    this.enabled = value;
    if (!value) this.skip();
  }
  async waitResumed(signal) {
    while (this.paused) {
      if (signal?.aborted) throw new DOMException("已停止", "AbortError");
      await new Promise((resolve) => setTimeout(resolve, 80));
    }
  }
  async speak(event, signal) {
    await this.waitResumed(signal);
    signal?.throwIfAborted();
    const utterance = new AbortController();
    this.utterance = utterance;
    signal = AbortSignal.any([utterance.signal, ...(signal ? [signal] : [])]);
    const generation = this.generation;
    this.current = event;
    this.onChange(event);
    if (!this.enabled) {
      try {
        await this.captionDelay(event.text, signal);
      } catch (error) {
        if (utterance.signal.reason !== "skip") throw error;
      } finally {
        if (this.utterance === utterance) this.utterance = null;
        if (generation === this.generation) {
          this.current = null;
          this.onChange(null);
        }
      }
      return;
    }
    let url;
    let objectURL;
    try {
      if (event.clip)
        url = new URL(`voices/${event.collection === "room" ? "room" : "demo"}/${event.clip}.mp3`, document.baseURI).href;
      else {
        this.fetchController = new AbortController();
        const response = await fetch(new URL("api/speech", document.baseURI), {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ actor: event.actor, text: event.text }),
          signal: AbortSignal.any([signal, this.fetchController.signal]),
        });
        if (!response.ok) {
          const error = await response.json();
          throw new Error(error.error || "语音合成失败。");
        }
        objectURL = URL.createObjectURL(await response.blob());
        url = objectURL;
      }
      if (generation !== this.generation) return;
      await this.waitResumed(signal);
      signal?.throwIfAborted();
      await new Promise((resolve, reject) => {
        let settled = false;
        const finish = () => {
          if (settled) return;
          settled = true;
          this.audio.pause();
          this.audio.removeEventListener("ended", finish);
          this.audio.removeEventListener("error", fail);
          signal?.removeEventListener("abort", abort);
          this.finish = null;
          resolve();
        };
        const fail = () => {
          finish();
          this.onNotice("语音暂时无法播放，已保留字幕。");
        };
        const abort = () => {
          finish();
          reject(new DOMException("已停止", "AbortError"));
        };
        this.finish = finish;
        this.audio.addEventListener("ended", finish);
        this.audio.addEventListener("error", fail);
        signal?.addEventListener("abort", abort, { once: true });
        this.audio.src = url;
        this.audio.play().catch(() => {
          if (settled || generation !== this.generation) return;
          this.paused = true;
          this.onNotice("浏览器暂停了声音，请点击「继续回放」。");
        });
      });
    } catch (error) {
      if (utterance.signal.reason === "skip") return;
      if (signal?.aborted || generation !== this.generation)
        throw new DOMException("已停止", "AbortError");
      this.onNotice(error.message);
      try {
        await this.captionDelay(event.text, signal);
      } catch (captionError) {
        if (utterance.signal.reason !== "skip") throw captionError;
      }
    } finally {
      if (objectURL) URL.revokeObjectURL(objectURL);
      if (this.utterance === utterance) this.utterance = null;
      if (generation === this.generation) {
        this.current = null;
        this.onChange(null);
      }
    }
  }
  async captionDelay(text, signal) {
    let remaining = Math.min(1800, Math.max(650, text.length * 25));
    while (remaining > 0) {
      await this.waitResumed(signal);
      signal?.throwIfAborted();
      await new Promise((resolve) => setTimeout(resolve, 80));
      remaining -= 80;
    }
  }
  pause() {
    this.paused = true;
    this.audio.pause();
  }
  async resume() {
    await this.context?.resume();
    this.paused = false;
    if (this.current && this.audio.src && this.finish) {
      try {
        await this.audio.play();
      } catch {
        this.paused = true;
        this.onNotice("声音仍被浏览器暂停，请再次点击「继续回放」。");
      }
    }
  }
  skip() {
    this.utterance?.abort("skip");
  }
  stop() {
    this.generation++;
    this.paused = false;
    this.utterance?.abort("stop");
    this.fetchController?.abort();
    this.finish?.();
    this.audio.pause();
    this.audio.removeAttribute("src");
    this.audio.load();
    this.current = null;

export const activeTask = (task) => ["running", "cancelling"].includes(task?.status);
export const taskToReconnect = (listing, runs) => listing.active || listing.recent.find((task) => runs.some((run) => {
  const status = task.status === "completed" ? "done" : task.status === "cancelled" ? "stopped" : "error";
  return run.id === task.client?.runId && (run.backendTaskId === task.id || ["stopped", "running", "paused"].includes(run.status)) &&
    ((run.backendCursor || 0) < task.lastSeq || run.status !== status);
}));
const pause = (ms, signal) => new Promise((resolve, reject) => {
  signal?.throwIfAborted();
  const finish = () => { signal?.removeEventListener("abort", abort); resolve(); };
  const timer = setTimeout(finish, ms);
  const abort = () => { clearTimeout(timer); reject(signal.reason); };
  signal?.addEventListener("abort", abort, { once: true });
});

export class BackgroundClient {
  constructor({ base = document.baseURI, request = fetch, interval = 900, sleep = pause } = {}) {
    this.base = base; this.request = request.bind(globalThis); this.interval = interval; this.sleep = sleep;
  }
  async call(path, { signal, ...options } = {}) {
    const response = await this.request(new URL(`api/tasks${path}`, this.base), { ...options, cache: "no-store",
      signal: signal ? AbortSignal.any([signal, AbortSignal.timeout(10000)]) : AbortSignal.timeout(10000) });
    const body = await response.json().catch(() => ({ error: "后台任务接口没有返回有效记录。" }));
    if (!response.ok) throw Object.assign(new Error(body.error || "后台任务连接失败。"), { status: response.status });
    return body;
  }
  async create(input, signal) {
    // Reusing the same requestId makes an uncertain POST safe to retry.
    for (let attempt = 0; ; attempt++) {
      try { return (await this.call("", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(input), signal })).task; }
      catch (error) {
        if (signal?.aborted || error.status || attempt >= 2) throw error;
        await this.sleep(400, signal);
      }
    }
  }
  list(signal) { return this.call("", { signal }); }
  cancel(id) { return this.call(`/${id}/cancel`, { method: "POST", headers: { "Content-Type": "application/json" }, body: "{}" }); }
  async snapshot(id, signal) {
    const events = []; let after = 0, result;
    do {
      result = await this.call(`/${id}?after=${after}&limit=200`, { signal });
      for (const event of result.events) {
        if (event.seq !== after + 1) throw new Error("后台任务事件顺序异常，不能恢复不完整记录。");
        events.push(event); after = event.seq;
      }
    } while (result.hasMore);
    return { task: result.task, events, cursor: after };
  }
  async follow(id, { cursor = 0, signal, onEvents, onTask = () => {}, onConnection = () => {} }) {
    let disconnected = false;
    for (;;) {
      signal.throwIfAborted();
      let result;
      try { result = await this.call(`/${id}?after=${cursor}&limit=200`, { signal }); }
      catch (error) {
        if (signal.aborted) throw signal.reason;
        if (error.status === 404 || error.status === 400) throw error;
        disconnected = true; onConnection("reconnecting"); await this.sleep(1500, signal); continue;
      }
      onConnection(disconnected ? "restored" : "connected");
      const batch = [];
      for (const event of result.events) {
        if (event.seq <= cursor) continue;
        if (event.seq !== cursor + 1) throw new Error("后台任务事件出现缺口，请重新打开房间接回任务。");
        batch.push(event); cursor = event.seq;
      }
      if (batch.length) await onEvents(batch, { catchup: disconnected, cursor });
      disconnected = false; onTask(result.task, cursor);
      if (!result.hasMore && !activeTask(result.task)) return result.task;
      if (!result.hasMore) await this.sleep(this.interval, signal);
    }
  }
}

